-- AP-16-04-02: provider-independent outbound command, attempts and status history.
alter type public.transport_message_direction add value if not exists 'outbound';
create type public.transport_delivery_status as enum ('pending','sending','accepted_by_provider','delivered','read','failed','delivery_ambiguous','blocked');
create type public.transport_send_result_class as enum ('started','provider_accepted','provider_rejected','rate_limited','transient_failure','ambiguous','blocked','configuration_failure');
create type public.transport_retry_classification as enum ('retryable','requires_reconciliation','terminal','configuration','human_review_required');
create type public.transport_provider_delivery_status as enum ('sent','delivered','read','failed');

create table public.transport_delivery_commands(
 id uuid primary key default gen_random_uuid(), provider public.conversation_transport_provider not null default 'whatsapp',
 internal_message_id uuid not null references public.conversation_messages(id) on delete restrict,
 conversation_id uuid not null references public.conversations(id) on delete restrict,
 transport_binding_id uuid not null references public.conversation_transport_bindings(id) on delete restrict,
 transport_identity_id uuid not null references public.conversation_transport_identities(id) on delete restrict,
 status public.transport_delivery_status not null default 'pending', attempt_count integer not null default 0 check(attempt_count between 0 and 3),
 provider_message_binding_id uuid references public.transport_message_bindings(id) on delete restrict,
 claim_token uuid, claimed_at timestamptz, accepted_at timestamptz, delivered_at timestamptz, read_at timestamptz, failed_at timestamptz,
 failure_code text check(failure_code is null or failure_code in ('provider_auth_error','rate_limited','provider_rejected','transient_provider_error','network_error','ambiguous_send_result','destination_invalid','conversation_not_sendable','binding_missing','stale_interaction','human_takeover_blocked','configuration_error')),
 retry_classification public.transport_retry_classification,
 created_at timestamptz not null default statement_timestamp(),updated_at timestamptz not null default statement_timestamp(),
 unique(provider,transport_binding_id,internal_message_id),check((status='sending')=(claim_token is not null))
);
create trigger transport_delivery_command_updated before update on public.transport_delivery_commands for each row execute function public.set_updated_at();
create table public.transport_send_attempts(
 attempt_id uuid primary key default gen_random_uuid(),delivery_command_id uuid not null references public.transport_delivery_commands(id) on delete restrict,
 attempt_number integer not null check(attempt_number between 1 and 3),started_at timestamptz not null default statement_timestamp(),finished_at timestamptz,
 result_class public.transport_send_result_class not null default 'started',failure_code text,provider_message_id text check(provider_message_id is null or length(provider_message_id) between 1 and 512),
 unique(delivery_command_id,attempt_number)
);
create table public.transport_delivery_events(
 id uuid primary key default gen_random_uuid(),delivery_command_id uuid references public.transport_delivery_commands(id) on delete restrict,
 provider_message_binding_id uuid references public.transport_message_bindings(id) on delete restrict,
 sender_scope text not null check(length(sender_scope) between 1 and 255),provider_message_id text not null check(length(provider_message_id) between 1 and 512),
 provider_status public.transport_provider_delivery_status not null,internal_mapped_status public.transport_delivery_status not null,
 occurred_at timestamptz not null,failure_code text,matched boolean not null,created_at timestamptz not null default statement_timestamp(),
 unique(sender_scope,provider_message_id,provider_status,occurred_at)
);
create trigger transport_delivery_events_append_only before update or delete on public.transport_delivery_events for each row execute function public.reject_append_only_change();
alter table public.transport_delivery_commands enable row level security;alter table public.transport_send_attempts enable row level security;alter table public.transport_delivery_events enable row level security;
revoke all on public.transport_delivery_commands,public.transport_send_attempts,public.transport_delivery_events from public,anon,authenticated;

create function public.claim_whatsapp_outbound_delivery(target_internal_message_id uuid) returns jsonb language plpgsql security definer set search_path=public,pg_temp as $$
declare m public.conversation_messages%rowtype;c public.conversations%rowtype;b public.conversation_transport_bindings%rowtype;i public.conversation_transport_identities%rowtype;d public.transport_delivery_commands%rowtype;p public.conversation_pending_interactions%rowtype;body text;token uuid:=gen_random_uuid();now_at timestamptz:=statement_timestamp();begin
 select * into m from public.conversation_messages where id=target_internal_message_id for update;if not found or m.direction<>'outbound' or m.message_kind<>'text' or m.actor_class not in ('admin','reviewer','system','ai') then raise exception 'conversation_not_sendable';end if;
 select * into c from public.conversations where id=m.conversation_id for update;
 select * into b from public.conversation_transport_bindings where conversation_id=c.id and provider='whatsapp' and status='active' for update;
 if b.id is null then raise exception 'binding_missing';end if;select * into i from public.conversation_transport_identities where id=b.transport_identity_id and status='active' for update;if i.id is null then raise exception 'binding_missing';end if;
 insert into public.transport_delivery_commands(internal_message_id,conversation_id,transport_binding_id,transport_identity_id) values(m.id,c.id,b.id,i.id) on conflict(provider,transport_binding_id,internal_message_id) do nothing;
 select * into d from public.transport_delivery_commands where provider='whatsapp' and transport_binding_id=b.id and internal_message_id=m.id for update;
 if d.status in ('sending','accepted_by_provider','delivered','read','delivery_ambiguous','blocked') then return jsonb_build_object('delivery_command_id',d.id,'claim_token',coalesce(d.claim_token,d.id),'destination','redacted','text','redacted','sender_scope',i.sender_scope,'status',case when d.status='blocked' then 'blocked' else 'replay' end);end if;
 if c.status<>'open' then update public.transport_delivery_commands set status='blocked',failure_code=case when c.status='human_review' then 'human_takeover_blocked' else 'conversation_not_sendable' end,retry_classification=case when c.status='human_review' then 'human_review_required' else 'terminal' end where id=d.id;return jsonb_build_object('delivery_command_id',d.id,'claim_token',d.id,'destination','redacted','text','redacted','sender_scope',i.sender_scope,'status','blocked');end if;
 select * into p from public.conversation_pending_interactions where prompt_message_id=m.id;
 if p.id is not null and (p.status<>'pending' or not exists(select 1 from public.conversation_runtime_states r where r.conversation_id=c.id and r.active_pending_interaction_id=p.id and r.runtime_status in ('awaiting_customer_answer','awaiting_evidence'))) then update public.transport_delivery_commands set status='blocked',failure_code='stale_interaction',retry_classification='terminal' where id=d.id;return jsonb_build_object('delivery_command_id',d.id,'claim_token',d.id,'destination','redacted','text','redacted','sender_scope',i.sender_scope,'status','blocked');end if;
 select t.body into body from public.conversation_message_text t where t.message_id=m.id;if body is null then raise exception 'conversation_not_sendable';end if;
 update public.transport_delivery_commands set status='sending',claim_token=token,claimed_at=now_at,attempt_count=attempt_count+1 where id=d.id returning * into d;
 insert into public.transport_send_attempts(delivery_command_id,attempt_number) values(d.id,d.attempt_count);
 insert into public.audit_log(actor_id,entity_type,entity_id,action,metadata) values(null,'transport_delivery_command',d.id,'whatsapp_delivery_attempt_started',jsonb_build_object('delivery_command_id',d.id,'internal_message_id',m.id,'attempt_number',d.attempt_count));
 return jsonb_build_object('delivery_command_id',d.id,'claim_token',token,'destination',i.external_identity,'text',body,'sender_scope',i.sender_scope,'status','sending');end$$;

create function public.revalidate_whatsapp_outbound_delivery(target_delivery_command_id uuid,target_claim_token uuid) returns boolean language plpgsql security definer set search_path=public,pg_temp as $$declare d public.transport_delivery_commands%rowtype;c public.conversations%rowtype;p public.conversation_pending_interactions%rowtype;begin select * into d from public.transport_delivery_commands where id=target_delivery_command_id for update;select * into c from public.conversations where id=d.conversation_id for update;if d.status<>'sending' or d.claim_token<>target_claim_token or c.status<>'open' or not exists(select 1 from public.conversation_transport_bindings b join public.conversation_transport_identities i on i.id=b.transport_identity_id where b.id=d.transport_binding_id and b.status='active' and i.status='active') then update public.transport_delivery_commands set status='blocked',claim_token=null,claimed_at=null,failure_code=case when c.status='human_review' then 'human_takeover_blocked' else 'conversation_not_sendable' end,retry_classification=case when c.status='human_review' then 'human_review_required' else 'terminal' end where id=d.id;return false;end if;select * into p from public.conversation_pending_interactions where prompt_message_id=d.internal_message_id;if p.id is not null and (p.status<>'pending' or not exists(select 1 from public.conversation_runtime_states r where r.conversation_id=d.conversation_id and r.active_pending_interaction_id=p.id)) then update public.transport_delivery_commands set status='blocked',claim_token=null,claimed_at=null,failure_code='stale_interaction',retry_classification='terminal' where id=d.id;return false;end if;return true;end$$;

create function public.complete_whatsapp_outbound_delivery(target_delivery_command_id uuid,target_claim_token uuid,target_success boolean,target_provider_message_id text,target_failure_code text,target_retry_classification public.transport_retry_classification,target_provider_accepted_at timestamptz) returns void language plpgsql security definer set search_path=public,pg_temp as $$declare d public.transport_delivery_commands%rowtype;i public.conversation_transport_identities%rowtype;mb public.transport_message_bindings%rowtype;result public.transport_send_result_class;begin select * into d from public.transport_delivery_commands where id=target_delivery_command_id and claim_token=target_claim_token and status='sending' for update;if not found then raise exception 'claim_lost';end if;select * into i from public.conversation_transport_identities where id=d.transport_identity_id;if target_success then insert into public.transport_message_bindings(provider,sender_scope,provider_message_id,internal_message_id,transport_identity_id,direction,provider_occurred_at) values('whatsapp',i.sender_scope,target_provider_message_id,d.internal_message_id,i.id,'outbound',target_provider_accepted_at) on conflict(provider,sender_scope,provider_message_id) do nothing returning * into mb;if mb.id is null then select * into mb from public.transport_message_bindings where provider='whatsapp' and sender_scope=i.sender_scope and provider_message_id=target_provider_message_id and internal_message_id=d.internal_message_id;if mb.id is null then raise exception 'provider_binding_conflict';end if;end if;update public.transport_delivery_commands set status='accepted_by_provider',provider_message_binding_id=mb.id,accepted_at=target_provider_accepted_at,claim_token=null,claimed_at=null where id=d.id;result:='provider_accepted';else result:=case target_failure_code when 'rate_limited' then 'rate_limited'::public.transport_send_result_class when 'transient_provider_error' then 'transient_failure'::public.transport_send_result_class when 'ambiguous_send_result' then 'ambiguous'::public.transport_send_result_class when 'provider_auth_error' then 'configuration_failure'::public.transport_send_result_class else 'provider_rejected'::public.transport_send_result_class end;update public.transport_delivery_commands set status=case when target_failure_code='ambiguous_send_result' then 'delivery_ambiguous'::public.transport_delivery_status else 'failed'::public.transport_delivery_status end,failure_code=target_failure_code,retry_classification=target_retry_classification,failed_at=statement_timestamp(),claim_token=null,claimed_at=null where id=d.id;end if;update public.transport_send_attempts set finished_at=statement_timestamp(),result_class=result,failure_code=target_failure_code,provider_message_id=target_provider_message_id where delivery_command_id=d.id and attempt_number=d.attempt_count;insert into public.audit_log(actor_id,entity_type,entity_id,action,metadata) values(null,'transport_delivery_command',d.id,case when target_success then 'whatsapp_delivery_attempt_completed' else 'whatsapp_delivery_attempt_failed' end,jsonb_build_object('delivery_command_id',d.id,'internal_message_id',d.internal_message_id,'attempt_number',d.attempt_count,'result_class',result));end$$;

create function public.reconcile_whatsapp_delivery_status(target_sender_scope text,target_provider_message_id text,target_provider_status public.transport_provider_delivery_status,target_occurred_at timestamptz,target_failure_code text) returns text language plpgsql security definer set search_path=public,pg_temp as $$declare mb public.transport_message_bindings%rowtype;d public.transport_delivery_commands%rowtype;mapped public.transport_delivery_status;begin mapped:=case target_provider_status when 'sent' then 'accepted_by_provider' when 'delivered' then 'delivered' when 'read' then 'read' else 'failed' end;select * into mb from public.transport_message_bindings where provider='whatsapp' and sender_scope=target_sender_scope and provider_message_id=target_provider_message_id and direction='outbound';if mb.id is not null then select * into d from public.transport_delivery_commands where provider_message_binding_id=mb.id for update;end if;insert into public.transport_delivery_events(delivery_command_id,provider_message_binding_id,sender_scope,provider_message_id,provider_status,internal_mapped_status,occurred_at,failure_code,matched) values(d.id,mb.id,target_sender_scope,target_provider_message_id,target_provider_status,mapped,target_occurred_at,target_failure_code,d.id is not null) on conflict do nothing;if d.id is null then return 'unmatched';end if;if mapped='read' or (mapped='delivered' and d.status not in ('read')) or (mapped='accepted_by_provider' and d.status not in ('delivered','read')) or (mapped='failed' and d.status not in ('delivered','read')) then update public.transport_delivery_commands set status=mapped,delivered_at=case when mapped='delivered' then target_occurred_at else delivered_at end,read_at=case when mapped='read' then target_occurred_at else read_at end,failed_at=case when mapped='failed' then target_occurred_at else failed_at end where id=d.id;end if;return 'matched';end$$;
revoke all on function public.claim_whatsapp_outbound_delivery(uuid),public.revalidate_whatsapp_outbound_delivery(uuid,uuid),public.complete_whatsapp_outbound_delivery(uuid,uuid,boolean,text,text,public.transport_retry_classification,timestamptz),public.reconcile_whatsapp_delivery_status(text,text,public.transport_provider_delivery_status,timestamptz,text) from public,anon,authenticated;
grant execute on function public.claim_whatsapp_outbound_delivery(uuid),public.revalidate_whatsapp_outbound_delivery(uuid,uuid),public.complete_whatsapp_outbound_delivery(uuid,uuid,boolean,text,text,public.transport_retry_classification,timestamptz),public.reconcile_whatsapp_delivery_status(text,text,public.transport_provider_delivery_status,timestamptz,text) to service_role;
comment on table public.transport_delivery_commands is 'No message text or destination copy. Provider acceptance remains distinct from delivery/read.';
comment on table public.transport_delivery_events is 'Minimal append-only status facts; no raw webhook payload or provider error text.';
